with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0106z04j', 'practice', 'Lecture A1 : un message de Camille', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce message, puis répondez aux questions.</p>', '<p>Salut Léa !</p><p>Tu es libre samedi ? Je vais au cinéma Le Rex avec Hugo. Le film commence à 18 h 30. On se retrouve devant le cinéma à 18 h.</p><p>Après le film, on va manger une pizza chez Mario. Réponds-moi avant vendredi !</p><p>À bientôt,</p><p>Camille</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• libre (adjectif) : rảnh\n• se retrouver (verbe) : gặp nhau\n• devant (préposition) : trước, phía trước\n• répondre (verbe) : trả lời\n• après (préposition) : sau, sau khi","explications":"• Tên ở đầu tin là người nhận, tên ở cuối tin là người viết.\n• Một tin có thể có nhiều giờ, nhiều ngày: đọc kỹ giờ đó là của việc gì.","kyNang":"A1-CE-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T12:00:00.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06x000', 'a1ce0106z04j', 1, 'qcm', 'Camille écrit à…', '{"options":["Léa","Mario","Hugo"]}'::jsonb, '{"answer":0}'::jsonb, '« Salut Léa ! » : tên người nhận đứng ở đầu tin.'), ('qmvxnw06x001', 'a1ce0106z04j', 2, 'qcm', 'Le cinéma, c''est quel jour ?', '{"options":["vendredi","dimanche","samedi"]}'::jsonb, '{"answer":2}'::jsonb, '« Tu es libre samedi ? ». Vendredi là hạn trả lời.'), ('qmvxnw06x002', 'a1ce0106z04j', 3, 'qcm', 'Où est le rendez-vous ?', '{"options":["chez Mario","chez Camille","devant le cinéma"]}'::jsonb, '{"answer":2}'::jsonb, '« On se retrouve devant le cinéma ».'), ('qmvxnw06x003', 'a1ce0106z04j', 4, 'fill', 'Le film commence à ______.', '{}'::jsonb, '{"accepted":"18 h 30|18h30|18 h30|18h 30"}'::jsonb, '« Le film commence à 18 h 30 ». Hẹn lúc 18 h, phim chiếu lúc 18 h 30.'), ('qmvxnw06x004', 'a1ce0106z04j', 5, 'fill', 'Après le film, ils vont manger ______.', '{}'::jsonb, '{"accepted":"une pizza|pizza|de la pizza"}'::jsonb, '« on va manger une pizza ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0207204k', 'practice', 'Lecture A1 : peux-tu m''aider ?', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce message, puis répondez aux questions.</p>', '<p>Bonjour Thomas,</p><p>Je déménage dimanche. Mon nouvel appartement est rue des Lilas, au numéro 12. Peux-tu m''aider ?</p><p>Rendez-vous chez moi à 9 h. Prends ta voiture, s''il te plaît. À midi, je t''invite au restaurant.</p><p>Merci !</p><p>Nadia</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• déménager (verbe) : chuyển nhà\n• un appartement (nom masculin) : căn hộ\n• aider (verbe) : giúp\n• une voiture (nom féminin) : ô tô\n• inviter (verbe) : mời","explications":"• Câu có « Peux-tu… ? » là câu nhờ giúp: đó thường là ý chính của tin.\n• Tìm từ chỉ nơi sau chez, à, rue.","kyNang":"A1-CE-1","vong":"hoc","thuTu":2}'::jsonb, '2026-11-01T12:00:01.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06x005', 'a1ce0207204k', 1, 'qcm', 'Qui demande de l''aide ?', '{"options":["un voisin","Nadia","Thomas"]}'::jsonb, '{"answer":1}'::jsonb, 'Tên cuối tin là người viết, chính là người nhờ.'), ('qmvxnw06x006', 'a1ce0207204k', 2, 'qcm', 'Que fait Nadia dimanche ?', '{"options":["Elle change d''appartement.","Elle travaille au restaurant.","Elle part en vacances."]}'::jsonb, '{"answer":0}'::jsonb, '« Je déménage dimanche » : déménager là chuyển nhà.'), ('qmvxnw06x007', 'a1ce0207204k', 3, 'fill', 'Le rendez-vous est à ______.', '{}'::jsonb, '{"accepted":"9 h|9h|9 heures"}'::jsonb, '« Rendez-vous chez moi à 9 h ».'), ('qmvxnw06x008', 'a1ce0207204k', 4, 'qcm', 'Que doit prendre Thomas ?', '{"options":["son vélo","sa voiture","le bus"]}'::jsonb, '{"answer":1}'::jsonb, '« Prends ta voiture ».'), ('qmvxnw06x009', 'a1ce0207204k', 5, 'fill', 'Le nouvel appartement est rue ______.', '{}'::jsonb, '{"accepted":"des Lilas|rue des Lilas"}'::jsonb, '« rue des Lilas ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0307204l', 'practice', 'Lecture A1 : bonjour de Nice', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce courriel, puis répondez aux questions.</p>', '<p><strong>De :</strong> Marie</p><p><strong>À :</strong> Julie</p><p><strong>Objet :</strong> Bonjour de Nice</p><p>Chère Julie,</p><p>Je suis à Nice avec mes parents pour une semaine. Il fait beau et chaud. Le matin, je vais à la plage. L''après-midi, nous visitons la ville.</p><p>Notre hôtel est près de la mer. Je rentre à Paris mardi.</p><p>Bises,</p><p>Marie</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une semaine (nom féminin) : tuần\n• la plage (nom féminin) : bãi biển\n• la mer (nom féminin) : biển\n• rentrer (verbe) : về, trở về\n• bises (nom féminin pluriel) : hôn nhẹ, cách chào cuối thư thân mật","explications":"• Email có sẵn phần De, À, Objet: đọc ba dòng đó là biết ai viết, viết cho ai, về việc gì.\n• Le matin là buổi sáng, l''après-midi là buổi chiều: đừng lẫn hai việc.","isPremium":true,"price":19000,"kyNang":"A1-CE-1","vong":"hoc","thuTu":3}'::jsonb, '2026-11-01T12:00:02.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y00a', 'a1ce0307204l', 1, 'qcm', 'Marie est à Nice avec…', '{"options":["ses amis","Julie","ses parents"]}'::jsonb, '{"answer":2}'::jsonb, '« avec mes parents ».'), ('qmvxnw06y00b', 'a1ce0307204l', 2, 'qcm', 'Quel temps fait-il ?', '{"options":["Il pleut.","Il fait beau.","Il fait froid."]}'::jsonb, '{"answer":1}'::jsonb, '« Il fait beau et chaud ».'), ('qmvxnw06y00c', 'a1ce0307204l', 3, 'qcm', 'Que fait Marie le matin ?', '{"options":["Elle visite la ville.","Elle reste à l''hôtel.","Elle va à la plage."]}'::jsonb, '{"answer":2}'::jsonb, '« Le matin, je vais à la plage ». Tham quan thành phố là buổi chiều.'), ('qmvxnw06y00d', 'a1ce0307204l', 4, 'fill', 'L''hôtel est près de ______.', '{}'::jsonb, '{"accepted":"la mer|mer"}'::jsonb, '« Notre hôtel est près de la mer ».'), ('qmvxnw06y00e', 'a1ce0307204l', 5, 'fill', 'Marie rentre à Paris ______.', '{}'::jsonb, '{"accepted":"mardi|le mardi"}'::jsonb, '« Je rentre à Paris mardi ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0407204m', 'practice', 'Lecture A1 : un mail du professeur', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce courriel, puis répondez aux questions.</p>', '<p>Bonjour à tous,</p><p>Demain, mardi, le cours de français n''est pas à 10 h. Il est à 11 h. Nous ne sommes pas dans la salle 8 mais dans la salle 15, au premier étage.</p><p>Apportez votre livre et un stylo. Il n''y a pas de cours jeudi.</p><p>Bonne soirée,</p><p>Monsieur Lambert</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• demain (adverbe) : ngày mai\n• une salle (nom féminin) : phòng học\n• un étage (nom masculin) : tầng\n• apporter (verbe) : mang theo\n• un stylo (nom masculin) : bút","explications":"• Khuôn « ne… pas… mais… »: phần sau mais mới là thông tin đúng.\n• Tin đổi lịch luôn có cả cũ lẫn mới, đừng chép nhầm giờ cũ.","isPremium":true,"price":19000,"kyNang":"A1-CE-1","vong":"hoc","thuTu":4}'::jsonb, '2026-11-01T12:00:03.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y00f', 'a1ce0407204m', 1, 'qcm', 'Qui écrit ce message ?', '{"options":["un élève","le directeur de l''hôtel","le professeur"]}'::jsonb, '{"answer":2}'::jsonb, '« le cours de français », ký tên « Monsieur Lambert ».'), ('qmvxnw06y00g', 'a1ce0407204m', 2, 'qcm', 'Demain, le cours est à…', '{"options":["10 h","15 h","11 h"]}'::jsonb, '{"answer":2}'::jsonb, '« n''est pas à 10 h. Il est à 11 h ».'), ('qmvxnw06y00h', 'a1ce0407204m', 3, 'fill', 'Le cours est dans la salle ______.', '{}'::jsonb, '{"accepted":"15"}'::jsonb, '« mais dans la salle 15 ». Sau mais mới là thông tin đúng.'), ('qmvxnw06y00i', 'a1ce0407204m', 4, 'qcm', 'Qu''est-ce qu''il faut apporter ?', '{"options":["un cahier et un stylo","un livre et un ordinateur","un livre et un stylo"]}'::jsonb, '{"answer":2}'::jsonb, '« Apportez votre livre et un stylo ».'), ('qmvxnw06y00j', 'a1ce0407204m', 5, 'qcm', 'Quel jour n''y a-t-il pas de cours ?', '{"options":["mardi","mercredi","jeudi"]}'::jsonb, '{"answer":2}'::jsonb, '« Il n''y a pas de cours jeudi ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0507204n', 'practice', 'Lecture A1 : un mot de la voisine', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce mot, puis répondez aux questions.</p>', '<p>Bonjour Monsieur Petit,</p><p>Je pars chez ma fille à Lyon de lundi à vendredi. Pouvez-vous donner à manger à mon chat, Minou, le matin et le soir ?</p><p>La clé est à la boulangerie. Le repas du chat est dans la cuisine.</p><p>Merci beaucoup !</p><p>Madame Roux, appartement 6</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un voisin, une voisine (nom) : hàng xóm\n• une fille (nom féminin) : con gái\n• un chat (nom masculin) : con mèo\n• une clé (nom féminin) : chìa khoá\n• une cuisine (nom féminin) : nhà bếp","explications":"• Pouvez-vous… ? là cách nhờ lịch sự, giữa người không thân.\n• Đề có thể hỏi điều phải suy ra một chút: sáng và tối là hai lần.","isPremium":true,"price":19000,"kyNang":"A1-CE-1","vong":"on","thuTu":5}'::jsonb, '2026-11-01T12:00:04.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y00k', 'a1ce0507204n', 1, 'qcm', 'Où va Madame Roux ?', '{"options":["à la boulangerie","chez Monsieur Petit","à Lyon"]}'::jsonb, '{"answer":2}'::jsonb, '« chez ma fille à Lyon ».'), ('qmvxnw06y00l', 'a1ce0507204n', 2, 'qcm', 'Elle part combien de temps ?', '{"options":["deux semaines","un seul jour","de lundi à vendredi"]}'::jsonb, '{"answer":2}'::jsonb, '« de lundi à vendredi ».'), ('qmvxnw06y00m', 'a1ce0507204n', 3, 'fill', 'Le chat s''appelle ______.', '{}'::jsonb, '{"accepted":"Minou"}'::jsonb, '« mon chat, Minou ».'), ('qmvxnw06y00n', 'a1ce0507204n', 4, 'qcm', 'Monsieur Petit donne à manger au chat…', '{"options":["une fois par semaine","une fois par jour","deux fois par jour"]}'::jsonb, '{"answer":2}'::jsonb, '« le matin et le soir » là hai lần một ngày.'), ('qmvxnw06y00o', 'a1ce0507204n', 5, 'fill', 'La clé est à ______.', '{}'::jsonb, '{"accepted":"la boulangerie|boulangerie"}'::jsonb, '« La clé est à la boulangerie ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0607204o', 'practice', 'Lecture A1 : deux messages', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces deux messages, puis répondez aux questions.</p>', '<p><strong>Message 1</strong></p><p>Salut Paul ! Mon anniversaire, c''est vendredi soir, chez moi, à 20 h. Mon adresse : 5, place de la République. Apporte de la musique ! Emma</p><p><strong>Message 2</strong></p><p>Bonjour Paul, le match de foot n''est pas dimanche. Il est samedi à 15 h. Rendez-vous au stade à 14 h 30. Karim</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un anniversaire (nom masculin) : sinh nhật\n• une adresse (nom féminin) : địa chỉ\n• un match (nom masculin) : trận đấu\n• un stade (nom masculin) : sân vận động\n• le soir (nom masculin) : buổi tối","explications":"• Hai tin: đọc câu hỏi xem hỏi tin nào rồi mới tìm, đừng trộn thông tin.\n• Làm bài này trong khoảng 8 phút để quen nhịp phòng thi.","isPremium":true,"price":19000,"kyNang":"A1-CE-1","vong":"chot","thuTu":6}'::jsonb, '2026-11-01T12:00:05.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y00p', 'a1ce0607204o', 1, 'qcm', 'Emma invite Paul pour…', '{"options":["son anniversaire","un match de foot","un concert"]}'::jsonb, '{"answer":0}'::jsonb, '« Mon anniversaire ».'), ('qmvxnw06y00q', 'a1ce0607204o', 2, 'qcm', 'La fête est…', '{"options":["dimanche soir","vendredi soir","samedi soir"]}'::jsonb, '{"answer":1}'::jsonb, '« vendredi soir ».'), ('qmvxnw06y00r', 'a1ce0607204o', 3, 'fill', 'La fête commence à ______.', '{}'::jsonb, '{"accepted":"20 h|20h|20 heures"}'::jsonb, '« à 20 h ».'), ('qmvxnw06y00s', 'a1ce0607204o', 4, 'fill', 'L''adresse d''Emma : 5, ______.', '{}'::jsonb, '{"accepted":"place de la République|5, place de la République|place de la Republique"}'::jsonb, '« 5, place de la République ».'), ('qmvxnw06y00t', 'a1ce0607204o', 5, 'qcm', 'Que doit apporter Paul chez Emma ?', '{"options":["un ballon","de la musique","un gâteau"]}'::jsonb, '{"answer":1}'::jsonb, '« Apporte de la musique ».'), ('qmvxnw06y00u', 'a1ce0607204o', 6, 'qcm', 'Le match de foot est…', '{"options":["dimanche","vendredi","samedi"]}'::jsonb, '{"answer":2}'::jsonb, '« Il est samedi à 15 h ».'), ('qmvxnw06y00v', 'a1ce0607204o', 7, 'fill', 'Le rendez-vous au stade est à ______.', '{}'::jsonb, '{"accepted":"14 h 30|14h30|14 h30|14h 30"}'::jsonb, '« Rendez-vous au stade à 14 h 30 ». 15 h là giờ bắt đầu trận.'), ('qmvxnw06y00w', 'a1ce0607204o', 8, 'qcm', 'Qui écrit le message 2 ?', '{"options":["Emma","Karim","Paul"]}'::jsonb, '{"answer":1}'::jsonb, 'Tên cuối tin 2 là Karim.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0707204p', 'practice', 'Lecture A1 : à gauche, à droite', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce texte, puis répondez aux questions.</p>', '<p>Je suis devant la mairie.</p><p>La banque est à gauche de la mairie.</p><p>La pharmacie est à droite de la mairie.</p><p>La poste est en face de la mairie.</p><p>Le café est à côté de la pharmacie.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• à gauche (expression) : bên trái\n• à droite (expression) : bên phải\n• tout droit (expression) : thẳng\n• en face de (expression) : đối diện\n• à côté de (expression) : bên cạnh","explications":"• droite và tout droit nhìn giống nhau nhưng khác hẳn nghĩa: phải và thẳng.\n• en face de là đối diện, à côté de là ngay bên cạnh.","kyNang":"A1-CE-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T12:00:06.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y00x', 'a1ce0707204p', 1, 'qcm', 'La banque est…', '{"options":["à gauche de la mairie","à droite de la mairie","en face de la mairie"]}'::jsonb, '{"answer":0}'::jsonb, '« La banque est à gauche de la mairie ».'), ('qmvxnw06y00y', 'a1ce0707204p', 2, 'qcm', 'La poste est…', '{"options":["à côté de la mairie","en face de la mairie","à gauche de la mairie"]}'::jsonb, '{"answer":1}'::jsonb, '« La poste est en face de la mairie ».'), ('qmvxnw06y00z', 'a1ce0707204p', 3, 'qcm', 'Le café est à côté de…', '{"options":["la pharmacie","la banque","la poste"]}'::jsonb, '{"answer":0}'::jsonb, '« Le café est à côté de la pharmacie ».'), ('qmvxnw06y010', 'a1ce0707204p', 4, 'qcm', '« À droite », c''est…', '{"options":["→","←","↑"]}'::jsonb, '{"answer":0}'::jsonb, 'à droite: bên phải.'), ('qmvxnw06y011', 'a1ce0707204p', 5, 'qcm', '« Tout droit », c''est…', '{"options":["←","→","↑"]}'::jsonb, '{"answer":2}'::jsonb, 'tout droit: đi thẳng. Đừng nhầm với à droite.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0807204q', 'practice', 'Lecture A1 : pour aller à la poste', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce plan et ces indications, puis répondez aux questions.</p>', '<p><img src="/images/doc-a1/ville.svg" alt="Plan de la ville avec six bâtiments, de A à F" /></p><p>Vous êtes à l''étoile. Vous regardez vers la droite du plan.</p><p><strong>1. La poste :</strong> allez tout droit. Prenez la première rue à gauche. La poste est à droite.</p><p><strong>2. La banque :</strong> allez tout droit. Passez la première rue. La banque est à droite, en face de la poste.</p><p><strong>3. L''école :</strong> allez tout droit. Prenez la première rue à droite. L''école est à droite.</p><p><strong>4. La pharmacie :</strong> allez tout droit. Prenez la deuxième rue à droite. La pharmacie est à gauche.</p><p><strong>5. Le musée :</strong> allez tout droit. Prenez la deuxième rue à gauche. Le musée est à droite.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une rue (nom féminin) : đường phố\n• prendre (verbe) : đi theo, rẽ vào\n• premier, première (adjectif) : thứ nhất\n• deuxième (adjectif) : thứ hai\n• une mairie (nom féminin) : toà thị chính","explications":"• Đặt ngón tay lên sơ đồ, đi từng câu một.\n• Sau khi rẽ, bên phải và bên trái của bạn đổi theo hướng đang đi, không còn theo tờ giấy.","kyNang":"A1-CE-2","vong":"hoc","thuTu":2}'::jsonb, '2026-11-01T12:00:07.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y012', 'a1ce0807204q', 1, 'qcm', 'La poste, c''est le bâtiment…', '{"options":["B","A","C"]}'::jsonb, '{"answer":0}'::jsonb, 'Rẽ trái ở phố thứ nhất là đi lên, tay phải là ô B.'), ('qmvxnw06y013', 'a1ce0807204q', 2, 'qcm', 'La banque, c''est le bâtiment…', '{"options":["F","E","D"]}'::jsonb, '{"answer":1}'::jsonb, 'Qua phố thứ nhất, bên phải là ô E, đối diện B.'), ('qmvxnw06y014', 'a1ce0807204q', 3, 'qcm', 'L''école, c''est le bâtiment…', '{"options":["D","E","A"]}'::jsonb, '{"answer":0}'::jsonb, 'Rẽ phải ở phố thứ nhất là đi xuống, tay phải lúc này là ô D.'), ('qmvxnw06y015', 'a1ce0807204q', 4, 'qcm', 'La pharmacie, c''est le bâtiment…', '{"options":["E","C","F"]}'::jsonb, '{"answer":2}'::jsonb, 'Rẽ phải ở phố thứ hai là đi xuống, tay trái lúc này là ô F.'), ('qmvxnw06y016', 'a1ce0807204q', 5, 'qcm', 'Le musée, c''est le bâtiment…', '{"options":["B","C","F"]}'::jsonb, '{"answer":1}'::jsonb, 'Rẽ trái ở phố thứ hai là đi lên, tay phải là ô C.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce0907204r', 'practice', 'Lecture A1 : au deuxième étage', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce plan et ce message, puis répondez aux questions.</p>', '<p><img src="/images/doc-a1/immeuble.svg" alt="Plan d''une école de trois niveaux" /></p><p>Bonjour Ana,</p><p>Bienvenue à l''école ! Entre par l''accueil, au rez-de-chaussée, et prends l''ascenseur.</p><p>Ton cours est au deuxième étage, à gauche. Pour ton inscription, va au premier étage, à gauche. Pour un café, reviens au rez-de-chaussée : la cafétéria est à gauche.</p><p>À tout à l''heure,</p><p>Sophie</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le rez-de-chaussée (nom masculin) : tầng trệt\n• un ascenseur (nom masculin) : thang máy\n• l''accueil (nom masculin) : quầy tiếp đón\n• une inscription (nom féminin) : việc đăng ký\n• une bibliothèque (nom féminin) : thư viện","explications":"• Tầng của Pháp tính từ rez-de-chaussée, nên premier étage là tầng 2 kiểu Việt Nam.\n• Đọc giao của hàng (tầng) và cột (trái, phải) trên sơ đồ.","isPremium":true,"price":19000,"kyNang":"A1-CE-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-01T12:00:08.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y017', 'a1ce0907204r', 1, 'qcm', 'Le cours d''Ana est…', '{"options":["dans la salle 12","dans la salle 21","à la bibliothèque"]}'::jsonb, '{"answer":1}'::jsonb, '« au deuxième étage, à gauche » trên sơ đồ là Salle 21.'), ('qmvxnw06y018', 'a1ce0907204r', 2, 'qcm', 'Pour l''inscription, Ana va…', '{"options":["au secrétariat","à l''accueil","à la bibliothèque"]}'::jsonb, '{"answer":0}'::jsonb, '« au premier étage, à gauche » trên sơ đồ là Secrétariat.'), ('qmvxnw06y019', 'a1ce0907204r', 3, 'qcm', 'La cafétéria est…', '{"options":["au premier étage","au rez-de-chaussée","au deuxième étage"]}'::jsonb, '{"answer":1}'::jsonb, '« la cafétéria est à gauche » ở « rez-de-chaussée », tầng trệt.'), ('qmvxnw06y01a', 'a1ce0907204r', 4, 'qcm', 'Au deuxième étage, à droite, il y a…', '{"options":["la salle 12","l''accueil","la bibliothèque"]}'::jsonb, '{"answer":2}'::jsonb, 'Nhìn hàng 2e étage, ô bên phải.'), ('qmvxnw06y01b', 'a1ce0907204r', 5, 'qcm', 'La salle 12 est…', '{"options":["au deuxième étage, à droite","au premier étage, à droite","au premier étage, à gauche"]}'::jsonb, '{"answer":1}'::jsonb, 'Nhìn hàng 1er étage, ô bên phải.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce1007304s', 'practice', 'Lecture A1 : chez moi', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce courriel, puis répondez aux questions.</p>', '<p>Salut Hugo !</p><p>Voici le chemin pour venir chez moi. Tu sors de la gare et tu tournes à droite. Tu vas tout droit dans la rue Pasteur. Au feu, tu tournes à gauche, rue du Moulin.</p><p>Tu passes devant une école. Ma maison est à droite, au numéro 9, en face du parc. La porte est bleue.</p><p>À samedi !</p><p>Inès</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le chemin (nom masculin) : đường đi\n• tourner (verbe) : rẽ\n• sortir (verbe) : đi ra\n• un feu (nom masculin) : đèn giao thông\n• une maison (nom féminin) : ngôi nhà","explications":"• Thư chỉ đường đi theo thứ tự: câu hỏi cũng đi theo thứ tự đó.\n• Tu tournes, tu vas, tu passes đều là việc người đọc phải làm: gạch chân các động từ này.","isPremium":true,"price":19000,"kyNang":"A1-CE-2","vong":"on","thuTu":4}'::jsonb, '2026-11-01T12:00:09.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y01c', 'a1ce1007304s', 1, 'qcm', 'Hugo arrive…', '{"options":["à la gare","à l''école","au parc"]}'::jsonb, '{"answer":0}'::jsonb, '« Tu sors de la gare ».'), ('qmvxnw06y01d', 'a1ce1007304s', 2, 'qcm', 'À la sortie de la gare, Hugo tourne…', '{"options":["au feu","à droite","à gauche"]}'::jsonb, '{"answer":1}'::jsonb, '« tu tournes à droite ».'), ('qmvxnw06y01e', 'a1ce1007304s', 3, 'qcm', 'Au feu, Hugo…', '{"options":["va tout droit","tourne à gauche","tourne à droite"]}'::jsonb, '{"answer":1}'::jsonb, '« Au feu, tu tournes à gauche ».'), ('qmvxnw06y01f', 'a1ce1007304s', 4, 'qcm', 'La maison est en face…', '{"options":["de la gare","du parc","de l''école"]}'::jsonb, '{"answer":1}'::jsonb, '« en face du parc ».'), ('qmvxnw06y01g', 'a1ce1007304s', 5, 'qcm', 'La porte de la maison est…', '{"options":["rouge","verte","bleue"]}'::jsonb, '{"answer":2}'::jsonb, '« La porte est bleue ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce1107304t', 'practice', 'Lecture A1 : quel est le bon chemin ?', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce plan et ces indications, puis répondez aux questions.</p>', '<p><img src="/images/doc-a1/chemins.svg" alt="Plan avec trois chemins, A, B et C, de la gare à l''hôtel" /></p><p>Vous sortez de la gare. Vous regardez vers la droite du plan.</p><p><strong>Indication 1 :</strong> allez tout droit. Au premier carrefour, tournez à gauche. Au carrefour suivant, tournez à droite. Au carrefour suivant, tournez à gauche. L''hôtel est au bout de la rue.</p><p><strong>Indication 2 :</strong> allez tout droit jusqu''au bout de la rue. Tournez à gauche. Allez tout droit jusqu''à l''hôtel.</p><p><strong>Indication 3 :</strong> tournez tout de suite à gauche. Allez tout droit jusqu''au bout de la rue. Tournez à droite. Allez tout droit jusqu''à l''hôtel.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un carrefour (nom masculin) : ngã tư\n• suivant, suivante (adjectif) : tiếp theo\n• au bout de (expression) : ở cuối\n• tout de suite (expression) : ngay lập tức\n• un parc (nom masculin) : công viên","explications":"• Lấy bút chì dò từng đường: mỗi câu chỉ dẫn là một đoạn.\n• Trong phòng thi, sai một bước là sai cả đường, nên đừng làm vội.","isPremium":true,"price":19000,"kyNang":"A1-CE-2","vong":"chot","thuTu":5}'::jsonb, '2026-11-01T12:00:10.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y01h', 'a1ce1107304t', 1, 'qcm', 'L''indication 1, c''est le chemin…', '{"options":["A","B","C"]}'::jsonb, '{"answer":2}'::jsonb, 'Thẳng, trái, phải, trái: đường C.'), ('qmvxnw06y01i', 'a1ce1107304t', 2, 'qcm', 'L''indication 2, c''est le chemin…', '{"options":["C","B","A"]}'::jsonb, '{"answer":2}'::jsonb, 'Thẳng tới cuối đường rồi rẽ trái: đường A.'), ('qmvxnw06y01j', 'a1ce1107304t', 3, 'qcm', 'L''indication 3, c''est le chemin…', '{"options":["A","C","B"]}'::jsonb, '{"answer":2}'::jsonb, 'Rẽ trái ngay, thẳng tới cuối, rẽ phải: đường B.'), ('qmvxnw06y01k', 'a1ce1107304t', 4, 'qcm', 'Sur le chemin A, vous passez devant…', '{"options":["le parc et le musée","l''école et la piscine","le parc et l''école"]}'::jsonb, '{"answer":0}'::jsonb, 'Đường A đi dọc hàng dưới, phía trên là parc và musée.'), ('qmvxnw06y01l', 'a1ce1107304t', 5, 'qcm', 'Sur le chemin B, à la fin, la piscine est…', '{"options":["à gauche","à droite","en face"]}'::jsonb, '{"answer":1}'::jsonb, 'Đi hướng phải trên hàng trên cùng, piscine nằm phía dưới, tức tay phải.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
