with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce20073052', 'practice', 'Lecture A1 : petites annonces', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces annonces, puis répondez aux questions.</p>', '<p><strong>Annonce A</strong></p><p>Chambre à louer, près de l''université. 350 € par mois. Tél. : 04 65 71 20 40.</p><p><strong>Annonce B</strong></p><p>Famille cherche baby-sitter le mercredi après-midi pour deux enfants, 5 et 8 ans. 12 € de l''heure.</p><p><strong>Annonce C</strong></p><p>Vends vélo bleu, très bon état, 80 €. Demandez Marc.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une annonce (nom féminin) : tin rao\n• louer (verbe) : thuê, cho thuê\n• chercher (verbe) : tìm\n• vendre (verbe) : bán\n• de l''heure (expression) : mỗi giờ","explications":"• Tin rao hay bỏ bớt từ: « Vends vélo » là « Je vends un vélo ».\n• Trước hết xác định mỗi tin là thuê, tìm người hay bán.","isPremium":true,"price":19000,"kyNang":"A1-CE-4","vong":"on","thuTu":4}'::jsonb, '2026-11-01T12:00:19.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y03g', 'a1ce20073052', 1, 'qcm', 'Un étudiant cherche un logement. Il regarde…', '{"options":["l''annonce C","l''annonce B","l''annonce A"]}'::jsonb, '{"answer":2}'::jsonb, '« Chambre à louer ».'), ('qmvxnw06y03h', 'a1ce20073052', 2, 'qcm', 'La baby-sitter travaille…', '{"options":["le mercredi après-midi","le samedi soir","le lundi matin"]}'::jsonb, '{"answer":0}'::jsonb, '« le mercredi après-midi ».'), ('qmvxnw06y03i', 'a1ce20073052', 3, 'qcm', 'Le vélo est…', '{"options":["noir","bleu","vert"]}'::jsonb, '{"answer":1}'::jsonb, '« Vends vélo bleu ».'), ('qmvxnw06y03j', 'a1ce20073052', 4, 'fill', 'La chambre coûte ______ par mois.', '{}'::jsonb, '{"accepted":"350 €|350 euros|350"}'::jsonb, '« 350 € par mois ».'), ('qmvxnw06y03k', 'a1ce20073052', 5, 'fill', 'Pour acheter le vélo, vous demandez ______.', '{}'::jsonb, '{"accepted":"Marc"}'::jsonb, '« Demandez Marc ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce21074053', 'practice', 'Lecture A1 : l''affiche de la fête', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cette affiche, puis répondez aux questions.</p>', '<p><strong>FÊTE DU QUARTIER</strong></p><p>Samedi 20 juin, de 16 h à 23 h</p><p>Place de la Mairie</p><p>Concerts gratuits</p><p>Repas : 10 €. Enfants : 5 €.</p><p>Parking gratuit derrière la mairie</p><p>S''il pleut, la fête est à la salle des sports.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une fête (nom féminin) : lễ hội\n• un quartier (nom masculin) : khu phố\n• un repas (nom masculin) : bữa ăn\n• derrière (préposition) : phía sau\n• il pleut (expression) : trời mưa","explications":"• Tờ thông tin: tìm nhanh ngày, nơi, giá.\n• S''il pleut là nếu trời mưa: câu này đổi địa điểm.","isPremium":true,"price":19000,"kyNang":"A1-CE-4","vong":"chot","thuTu":5}'::jsonb, '2026-11-01T12:00:20.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y03l', 'a1ce21074053', 1, 'qcm', 'La fête est…', '{"options":["dimanche 20 juin","samedi 20 juin","samedi 23 juin"]}'::jsonb, '{"answer":1}'::jsonb, '« Samedi 20 juin ».'), ('qmvxnw06y03m', 'a1ce21074053', 2, 'qcm', 'La fête finit à…', '{"options":["23 h","16 h","20 h"]}'::jsonb, '{"answer":0}'::jsonb, '« de 16 h à 23 h ».'), ('qmvxnw06y03n', 'a1ce21074053', 3, 'qcm', 'Les concerts coûtent…', '{"options":["10 €","0 €","5 €"]}'::jsonb, '{"answer":1}'::jsonb, '« Concerts gratuits ».'), ('qmvxnw06y03o', 'a1ce21074053', 4, 'fill', 'Le repas pour un adulte coûte ______.', '{}'::jsonb, '{"accepted":"10 €|10 euros|10"}'::jsonb, '« Repas : 10 € ».'), ('qmvxnw06y03p', 'a1ce21074053', 5, 'fill', 'Le parking est derrière ______.', '{}'::jsonb, '{"accepted":"la mairie|mairie"}'::jsonb, '« derrière la mairie ».'), ('qmvxnw06y03q', 'a1ce21074053', 6, 'fill', 'S''il pleut, la fête est à ______.', '{}'::jsonb, '{"accepted":"la salle des sports|salle des sports"}'::jsonb, '« la fête est à la salle des sports ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce22074054', 'practice', 'Lecture A1 : copiez sans faute', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez cette fiche, puis répondez aux questions.</p>', '<div class="mcf-bang"><table><thead><tr><th>Fiche d''inscription</th><th></th></tr></thead><tbody><tr><td>Nom</td><td>Lefèvre</td></tr><tr><td>Prénom</td><td>Hélène</td></tr><tr><td>Adresse</td><td>7, rue de l''Église</td></tr><tr><td>Ville</td><td>Besançon</td></tr><tr><td>Date de naissance</td><td>12 février 1998</td></tr><tr><td>Nationalité</td><td>française</td></tr></tbody></table></div>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un nom (nom masculin) : họ\n• un prénom (nom masculin) : tên\n• une ville (nom féminin) : thành phố\n• la date de naissance (expression) : ngày sinh\n• une nationalité (nom féminin) : quốc tịch","explications":"• Chép từng chữ, kể cả dấu và chữ hoa ở tên riêng.\n• Chép xong nhìn lại tài liệu một lần, so từng chữ.","kyNang":"A1-CE-5","vong":"hoc","thuTu":1}'::jsonb, '2026-11-01T12:00:21.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y03r', 'a1ce22074054', 1, 'fill', 'Nom : ______', '{}'::jsonb, '{"accepted":"Lefèvre"}'::jsonb, '« Lefèvre » có dấu è.'), ('qmvxnw06y03s', 'a1ce22074054', 2, 'fill', 'Prénom : ______', '{}'::jsonb, '{"accepted":"Hélène"}'::jsonb, '« Hélène » có é rồi è.'), ('qmvxnw06y03t', 'a1ce22074054', 3, 'fill', 'Adresse : 7, rue de ______', '{}'::jsonb, '{"accepted":"l''Église|rue de l''Église|7, rue de l''Église"}'::jsonb, '« rue de l''Église »: có dấu nháy và É.'), ('qmvxnw06y03u', 'a1ce22074054', 4, 'fill', 'Ville : ______', '{}'::jsonb, '{"accepted":"Besançon"}'::jsonb, '« Besançon » có ç.'), ('qmvxnw06y03v', 'a1ce22074054', 5, 'fill', 'Mois de naissance : ______', '{}'::jsonb, '{"accepted":"février"}'::jsonb, '« février » có dấu é.'), ('qmvxnw06y03w', 'a1ce22074054', 6, 'fill', 'Nationalité : ______', '{}'::jsonb, '{"accepted":"française"}'::jsonb, '« française » có ç.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce23074055', 'practice', 'Lecture A1 : réponse courte', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce message, puis répondez aux questions.</p>', '<p>Bonjour Chloé,</p><p>Je t''attends demain à 15 h 45 au café de la Gare, à côté de la pharmacie. Le café coûte 3 €. Après, on va au musée Rodin. Le billet coûte 12 €.</p><p>À demain !</p><p>Jérôme</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• attendre (verbe) : đợi\n• demain (adverbe) : ngày mai\n• un musée (nom masculin) : bảo tàng\n• un billet (nom masculin) : vé\n• coûter (verbe) : có giá","explications":"• Câu trả lời ngắn: chỉ viết thông tin được hỏi, không cần cả câu.\n• Giữ nguyên số và đơn vị: 3 €, 15 h 45.","kyNang":"A1-CE-5","vong":"hoc","thuTu":2}'::jsonb, '2026-11-01T12:00:22.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y03x', 'a1ce23074055', 1, 'fill', 'À quelle heure est le rendez-vous ? ______', '{}'::jsonb, '{"accepted":"15 h 45|15h45|15 h45|15h 45"}'::jsonb, '« à 15 h 45 ».'), ('qmvxnw06y03y', 'a1ce23074055', 2, 'fill', 'Où est le rendez-vous ? Au café de ______', '{}'::jsonb, '{"accepted":"la Gare|café de la Gare|au café de la Gare"}'::jsonb, '« au café de la Gare ».'), ('qmvxnw06y03z', 'a1ce23074055', 3, 'fill', 'Le café est à côté de quoi ? De ______', '{}'::jsonb, '{"accepted":"la pharmacie|pharmacie"}'::jsonb, '« à côté de la pharmacie ».'), ('qmvxnw06y040', 'a1ce23074055', 4, 'fill', 'Combien coûte un café ? ______', '{}'::jsonb, '{"accepted":"3 €|3 euros|3"}'::jsonb, '« Le café coûte 3 € ».'), ('qmvxnw06y041', 'a1ce23074055', 5, 'fill', 'Quel musée vont-ils voir ? Le musée ______', '{}'::jsonb, '{"accepted":"Rodin"}'::jsonb, '« au musée Rodin ».'), ('qmvxnw06y042', 'a1ce23074055', 6, 'fill', 'Qui écrit ce message ? ______', '{}'::jsonb, '{"accepted":"Jérôme"}'::jsonb, '« Jérôme » có é và ô.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce24074056', 'practice', 'Lecture A1 : trouvez et écrivez', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ce dépliant, puis répondez aux questions.</p>', '<p><strong>BIBLIOTHÈQUE VICTOR-HUGO</strong></p><p>Ouverte du mardi au samedi, de 10 h à 18 h</p><p>2, boulevard Gambetta</p><p>Inscription gratuite pour les étudiants</p><p>Livres, journaux et films</p><p>Atelier de lecture pour les enfants le mercredi à 14 h</p><p>Courriel : contact@biblio-hugo.example</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une bibliothèque (nom féminin) : thư viện\n• un journal, des journaux (nom masculin) : tờ báo\n• un atelier (nom masculin) : lớp thực hành\n• la lecture (nom féminin) : việc đọc\n• un courriel (nom masculin) : email","explications":"• Dépliant có nhiều dòng ngắn: đọc từ khoá trong câu hỏi rồi quét tìm.\n• Email phải chép đúng từng ký tự, kể cả @ và dấu chấm.","isPremium":true,"price":19000,"kyNang":"A1-CE-5","vong":"on","thuTu":3}'::jsonb, '2026-11-01T12:00:23.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y043', 'a1ce24074056', 1, 'fill', 'Nom de la bibliothèque : ______', '{}'::jsonb, '{"accepted":"Victor-Hugo|Bibliothèque Victor-Hugo|Victor Hugo"}'::jsonb, '« BIBLIOTHÈQUE VICTOR-HUGO ».'), ('qmvxnw06y044', 'a1ce24074056', 2, 'fill', 'Adresse : 2, boulevard ______', '{}'::jsonb, '{"accepted":"Gambetta|boulevard Gambetta|2, boulevard Gambetta"}'::jsonb, '« 2, boulevard Gambetta ».'), ('qmvxnw06y045', 'a1ce24074056', 3, 'fill', 'La bibliothèque ferme à ______.', '{}'::jsonb, '{"accepted":"18 h|18h|18 heures"}'::jsonb, '« de 10 h à 18 h ».'), ('qmvxnw06y046', 'a1ce24074056', 4, 'fill', 'L''inscription est gratuite pour les ______.', '{}'::jsonb, '{"accepted":"étudiants"}'::jsonb, '« pour les étudiants ».'), ('qmvxnw06y047', 'a1ce24074056', 5, 'fill', 'L''atelier des enfants est le ______.', '{}'::jsonb, '{"accepted":"mercredi"}'::jsonb, '« le mercredi à 14 h ».'), ('qmvxnw06y048', 'a1ce24074056', 6, 'fill', 'Courriel : ______', '{}'::jsonb, '{"accepted":"contact@biblio-hugo.example"}'::jsonb, '« contact@biblio-hugo.example »: chép đủ từng ký tự.')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('a1ce25074057', 'practice', 'Lecture A1 : dix petites réponses', 'A1', array['Lecture']::text[], 'practice', null, null, '<p>Lisez ces trois documents, puis répondez aux questions.</p>', '<p><strong>Document 1 : un message</strong></p><p>Salut Théo ! Le train arrive à Grenoble à 11 h 20. Je t''attends sur le quai 4. Bises, Maël</p><p><strong>Document 2 : une affiche</strong></p><p>Marché de Noël, place Stanislas, du 5 au 24 décembre. Entrée libre.</p><p><strong>Document 3 : une carte de visite</strong></p><p>Docteur Benoît Girard, 18, rue Émile-Zola. Tél. : 04 65 71 55 60.</p>', null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un quai (nom masculin) : sân ga\n• un marché (nom masculin) : chợ\n• Noël (nom masculin) : Giáng sinh\n• une carte de visite (expression) : danh thiếp\n• un médecin (nom masculin) : bác sĩ","explications":"• Mười câu trong khoảng 6 phút: tìm thật nhanh, chép thật đúng.\n• Tên riêng có dấu lạ như ë, î, É: nhìn kỹ từng chữ.","isPremium":true,"price":19000,"kyNang":"A1-CE-5","vong":"chot","thuTu":4}'::jsonb, '2026-11-01T12:00:24.000Z') returning id) insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation) select v.* from e, (values ('qmvxnw06y049', 'a1ce25074057', 1, 'fill', 'Le train arrive dans quelle ville ? ______', '{}'::jsonb, '{"accepted":"Grenoble"}'::jsonb, '« à Grenoble ».'), ('qmvxnw06y04a', 'a1ce25074057', 2, 'fill', 'À quelle heure ? ______', '{}'::jsonb, '{"accepted":"11 h 20|11h20|11 h20|11h 20"}'::jsonb, '« à 11 h 20 ».'), ('qmvxnw06y04b', 'a1ce25074057', 3, 'fill', 'Sur quel quai ? Le quai ______', '{}'::jsonb, '{"accepted":"4"}'::jsonb, '« sur le quai 4 ».'), ('qmvxnw06y04c', 'a1ce25074057', 4, 'fill', 'Qui écrit le message ? ______', '{}'::jsonb, '{"accepted":"Maël"}'::jsonb, '« Maël » có ë.'), ('qmvxnw06y04d', 'a1ce25074057', 5, 'fill', 'Où est le marché ? Place ______', '{}'::jsonb, '{"accepted":"Stanislas|place Stanislas"}'::jsonb, '« place Stanislas ».'), ('qmvxnw06y04e', 'a1ce25074057', 6, 'fill', 'Le marché finit le ______ décembre.', '{}'::jsonb, '{"accepted":"24"}'::jsonb, '« du 5 au 24 décembre ».'), ('qmvxnw06y04f', 'a1ce25074057', 7, 'fill', 'L''entrée est ______.', '{}'::jsonb, '{"accepted":"libre"}'::jsonb, '« Entrée libre ».'), ('qmvxnw06y04g', 'a1ce25074057', 8, 'fill', 'Nom du médecin : Benoît ______', '{}'::jsonb, '{"accepted":"Girard"}'::jsonb, '« Benoît Girard ».'), ('qmvxnw06y04h', 'a1ce25074057', 9, 'fill', 'Adresse du médecin : 18, rue ______', '{}'::jsonb, '{"accepted":"Émile-Zola|rue Émile-Zola|Emile Zola|18, rue Émile-Zola"}'::jsonb, '« 18, rue Émile-Zola ».'), ('qmvxnw06y04i', 'a1ce25074057', 10, 'fill', 'Téléphone du médecin : ______', '{}'::jsonb, '{"accepted":"04 65 71 55 60|0465715560"}'::jsonb, '« 04 65 71 55 60 ».')) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

do $$
declare n int;
begin
  select count(*) into n from public.exercises where id like 'a1ce%';
  if n <> 25 then raise exception 'có % bài Đọc A1, cần 25', n; end if;
end $$;
